    /** Every sound by name, including the {@code barbarian_death} alias. */
    public static Map<String, DeferredHolder<SoundEvent, SoundEvent>> all() {
        return Collections.unmodifiableMap(BY_NAME);
    }

    public static boolean isValidSound(String sound) {
        return BY_NAME.containsKey(sound);
    }

    /** The sound event of that name (case insensitive), or null. Only valid after registration. */
    @Nullable
    public static SoundEvent getSoundEventFromString(String name) {
        DeferredHolder<SoundEvent, SoundEvent> holder = BY_NAME.get(name.toLowerCase(Locale.ROOT));
        return holder == null ? null : holder.get();
    }
